# Exception handling
if PY3:
    def get_exception_info():
        exc_type, exc_value, tb = sys.exc_info()
        return exc_type, exc_value, tb

    def reraise(tp, value, tb=None):
        if value.__traceback__ is not tb:
            raise value.with_traceback(tb)
        raise value

    def raise_from(value, from_value):
        raise value from from_value

    def chain_exceptions(exc, *exceptions):
        for e in exceptions:
            if isinstance(exc, e.__class__):
                return True
        return False

    def with_context(exc, context):
        exc.__context__ = context
        return exc

    def raise_with_traceback(tb):
        raise sys.exc_info()[1].with_traceback(tb)
else:
    def get_exception_info():
        exc_type, exc_value, tb = sys.exc_info()
        return exc_type, exc_value, tb

    def reraise(tp, value, tb=None):
        raise tp, value, tb

    def raise_from(value, from_value):
        raise value

    def chain_exceptions(exc, *exceptions):
        for e in exceptions:
            if isinstance(exc, e):
                return True
        return False

    def with_context(exc, context):
        exc.__context__ = context
        return exc

    def raise_with_traceback(tb):
        raise sys.exc_info()[1], None, tb

